/** Values both the page and the Worker read. Nothing here is secret. */

/** The public repository the program and the plugin are published from (generated by scripts/export-public.mjs; the app repository stays private). The one place this address is written. */
export const PUBLIC_REPO_URL = 'https://github.com/agentvms/files-direct-cli';
/** Where a version's package file is attached to its release in the public repository (the release workflow names it so). */
export const publicReleaseTarball = (version: string): string => `${PUBLIC_REPO_URL}/releases/download/v${version}/files-direct-${version}.tgz`;

/**
 * The public half of the key that signs the double-click app's list of updates (files-direct-34): the raw 32 bytes of an Ed25519 key, in base64.
 * Made by the Factory lead; the secret half is only ever a secret (FD_UPDATE_SIGNING_KEY) of the public repository's release workflow. With an empty key a copy of the app never updates itself.
 */
export const UPDATE_PUBLIC_KEY = 'DWKN0R/GF/YjYe5KKyJkwfD7qJTk6NG0QCaM1ILp/2g=';
/**
 * Where the app's files are attached to a release in the public repository: the Worker streams them from here under /desktop/ and keeps nothing.
 * A file with a version in its name comes from that version's own release, so a download page or a list that is a few minutes old still finds it after the next
 * release is out; only the list of updates (feed.json and its signature) is the latest release's.
 */
export const publicReleaseAsset = (name: string): string => {
  const version = /^files-direct(?:-setup)?-(\d{1,4}\.\d{1,4}\.\d{1,4})-/.exec(name)?.[1];
  return version ? `${PUBLIC_REPO_URL}/releases/download/v${version}/${name}` : `${PUBLIC_REPO_URL}/releases/latest/download/${name}`;
};

/** Cloudflare's public addresses for finding a direct route (3478 and 443 for networks that block 3478). */
export const ICE_URLS = ['stun:stun.cloudflare.com:3478', 'stun:stun.cloudflare.com:443'];

/** Signalling: the largest message the room server passes on, in bytes. */
export const MAX_SIGNAL_BYTES = 16 * 1024;

/** Longest a room lives without being closed by its sender, in milliseconds. */
export const ROOM_MAX_AGE_MS = 24 * 60 * 60 * 1000;

/** Rooms one hashed address may open per hour and per day. */
export const ROOM_CREATE_LIMIT_HOUR = 20;
export const ROOM_CREATE_LIMIT_DAY = 100;
export const HOUR_MS = 60 * 60 * 1000;
export const DAY_MS = 24 * HOUR_MS;

/** Problem reports: what a person may send, how often, and how long a closed one is kept. */
export const REPORT_TEXT_MAX = 4000;
/** The connection facts that may come with a report. */
export const REPORT_FACTS_MAX = 3000;
export const REPORT_LIMIT_PER_HOUR = 5;
export const REPORT_RETENTION_MS = 90 * DAY_MS;
/** Report attachments (pictures, one recording, its still frames). See docs/REPORTS.md. */
export const REPORT_IMAGES_MAX = 5;
export const REPORT_IMAGE_BYTES = 5 * 1024 * 1024;
export const REPORT_REC_BYTES = 40 * 1024 * 1024;
export const REPORT_REC_SECONDS = 180;
export const REPORT_KEYFRAMES_MAX = 24;
export const REPORT_KEYFRAME_BYTES = 300 * 1024;
/** Files may be added to a report only this long after it was filed. */
export const REPORT_ATTACH_WINDOW_MS = 15 * 60 * 1000;
/** A recording that never got its still frames is deleted after this long. */
export const REPORT_STALE_MS = HOUR_MS;
/** The test lane (docs/TEST-LANE.md): the request header that marks a test report or room, and how long a left-over test report lives. */
export const TEST_LANE_HEADER = 'x-fd-test-lane';
/** The same token as a cookie: a browser cannot add a header to its own socket, so a browser run marks its rooms this way. */
export const TEST_LANE_COOKIE = 'fd-test-lane';
export const TEST_LANE_SWEEP_MS = HOUR_MS;
/** All stored attachment bytes together; past it new ones are refused (keeps us inside Cloudflare's free storage). */
export const REPORT_STORE_CAP_BYTES = 5 * 1024 * 1024 * 1024;
/** File uploads one hashed address may make per hour (a full report is at most 7). */
export const REPORT_UPLOAD_LIMIT_PER_HOUR = 40;
/** The record of every room (docs/RECORDS.md): how long it is kept, and how often the store looks for records past that. */
export const RECORD_KEEP_DAYS = 30;
export const RECORD_SWEEP_MS = DAY_MS;
export const REPORT_STATUSES = ['open', 'working', 'shipped', 'reopened', 'closed'] as const;
export type ReportStatus = (typeof REPORT_STATUSES)[number];
/** The issue id the team may attach to a report: short, no spaces, never free text. */
export const REPORT_REF = /^(?=.{1,64}$)[A-Za-z0-9][A-Za-z0-9._:-]*$/;

/**
 * A block is the unit of checking and of sending again: its own SHA-256, written to disk, then confirmed.
 * One constant, so the size can be tuned in one place. Memory on the receiving side holds at most one block per channel.
 */
export const BLOCK_SIZE = 4 * 1024 * 1024;

/** A block crosses the channel as pieces of at most this many bytes (safe on every browser's data channel). */
export const PIECE_SIZE = 64 * 1024;

/**
 * Small previews of photos (files-direct-32, docs/PROTOCOL.md "Previews"). The receiver says it takes them; the sender makes them on its own device and sends them over the same
 * connection, one frame each, before the answer. How many, how big across and how many bytes each is depends on the route: through our servers they stay tiny, because they count against the meter.
 */
export interface PreviewLimits {
  /** Most previews of one batch. */
  count: number;
  /** Longest side of a preview, in pixels. */
  edge: number;
  /** Most bytes of one preview (the picture itself, before base64). */
  bytes: number;
}
export const PREVIEW_LIMITS: { direct: PreviewLimits; relay: PreviewLimits } = {
  direct: { count: 30, edge: 480, bytes: 40 * 1024 },
  relay: { count: 12, edge: 240, bytes: 12 * 1024 },
};
export const previewLimits = (relay: boolean): PreviewLimits => (relay ? PREVIEW_LIMITS.relay : PREVIEW_LIMITS.direct);
/** The kinds of file a sender may try to make a preview of (never SVG). A file that cannot be decoded here (HEIC in Chrome, say) simply has none. */
export const PREVIEW_SOURCE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif', 'image/heic', 'image/heif'];
/** A file bigger than this is not decoded for a preview. */
export const PREVIEW_SOURCE_MAX_BYTES = 50 * 1000 * 1000;
/** The kinds of picture a preview frame may hold. */
export const PREVIEW_TYPES = ['image/jpeg', 'image/webp'];
/** The sender gives up on one picture after this long, and on all of a batch's previews after the longer one. Previews never hold anything else up. */
export const PREVIEW_ONE_MS = 4000;
export const PREVIEW_TOTAL_MS = 20_000;

/** The largest block size a receiver accepts from the other side. */
export const MAX_BLOCK_SIZE = 16 * 1024 * 1024;

/** Blocks of one batch that may be sent and not yet confirmed. Bounds what is in flight, whatever the file size. */
export const WINDOW_BLOCKS = 4;

/** A block that fails its check this many times fails the file. */
export const MAX_BLOCK_TRIES = 3;

/** Waiting channel bytes: stop sending above HIGH, go on when the channel says it is below LOW. */
export const HIGH_WATER = 1024 * 1024;
export const LOW_WATER = 256 * 1024;

/** Wrong codes (or wrong passwords) in a row from one hashed address before it is slowed. */
export const WRONG_TRIES_FREE = 10;
/** The first wait once slowed, doubling with every further wrong try, never more than the cap. */
export const SLOW_START_MS = 30 * 1000;
export const SLOW_CAP_MS = 60 * 60 * 1000;
/** A run of wrong tries is forgotten after this long without one. */
export const WRONG_STREAK_EXPIRY_MS = 24 * 60 * 60 * 1000;

/** How long a stranger may wait at the door (a password to type, or the sender's answer) before being turned away. */
export const KNOCK_TIMEOUT_MS = 2 * 60 * 1000;
/** The longest note an asker may add to a request for files (files-direct-28), in characters, counted on the side that shows it. */
export const ASK_NOTE_MAX_CHARS = 200;
/** The longest password the sender may set, in characters. */
export const PASSWORD_MAX_CHARS = 200;
